rss.channel:
Vietnamese Waves™ & Technocrat Press — Bilingual Books, Audio Demos & Engineering Visuals
{{ .Permalink }}
Collector-grade bilingual English-Vietnamese folklore, sacred myths, historical epics, interactive audio companions, and system design blueprints by Tuan-Hiep TRAN.
en-us
{{ now.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}

{{- $allPages := where .Site.RegularPages "Params.robotsNoIndex" "ne" true -}}
{{- range $allPages -}}
  {{- $isBook := eq .Section "books" -}}
  {{- $isDemo := eq .Section "demo" -}}
  {{- $hasImg := isset .Params "images" -}}
  {{- if or $isBook $isDemo $hasImg -}}
    {{- $img := "" -}}
    {{- if $hasImg -}}
      {{- $img = index .Params.images 0 -}}
    {{- else if $isDemo -}}
      {{- $rp := .RelPermalink -}}
      {{- if in $rp "folk-tales" -}}
        {{- $img = "/images/books/vietnamese-folk-tales-treasury.jpg" -}}
      {{- else if in $rp "myths" -}}
        {{- $img = "/images/books/vietnamese-myths-and-legends.jpg" -}}
      {{- else if in $rp "learn-vietnamese" -}}
        {{- $img = "/images/books/learn-vietnamese-stories.jpg" -}}
      {{- else if in $rp "heroes" -}}
        {{- $img = "/images/books/vietnamese-heroes-epics.jpg" -}}
      {{- end -}}
    {{- end -}}
    {{- if $img -}}
      {{- $absImg := $img | absURL -}}
      {{- $rawDesc := .Description | default .Summary | default .Title -}}
      {{- $cleanDesc := replace ($rawDesc | plainify | htmlUnescape) "]]>" "" -}}
      {{- $cleanTitle := .Title | htmlUnescape | htmlEscape -}}
      {{- $pub := .Date -}}
      {{- if $pub.IsZero -}}{{- $pub = now -}}{{- end -}}
      {{- $mime := "image/jpeg" -}}
      {{- if hasSuffix (lower $img) ".png" -}}{{- $mime = "image/png" -}}{{- end }}


  {{ $cleanTitle }}
  {{ .Permalink }}
  {{ .Permalink }}
  {{ $pub.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}
  {{ $cleanDesc }}



    {{- end -}}
  {{- end -}}
{{- end }}
